create table if not exists messages (id bigint generated by default as identity primary key, name text not null, email text not null, message text not null, created_at timestamptz default now());
create table if not exists feedback (id bigint generated by default as identity primary key, name text not null, message text not null, created_at timestamptz default now());
create table if not exists doubts (id bigint generated by default as identity primary key, name text not null, email text not null, description text not null, attachment_url text, created_at timestamptz default now());
insert into storage.buckets (id, name, public) values ('doubt-files', 'doubt-files', true) on conflict (id) do nothing;